# area: paramspec_concatenate
# hypothesis: A decorator factory generic in both a TypeVar and a ParamSpec keeps the wrapped signature through nested decorators, so a wrong argument type or keyword is rejected statically and fails at runtime.
from collections.abc import Callable
from typing import Concatenate, reveal_type


def retry[**P, R](times: int) -> Callable[[Callable[P, R]], Callable[P, R]]:
    def wrap(fn: Callable[P, R]) -> Callable[P, R]:
        def inner(*args: P.args, **kwargs: P.kwargs) -> R:
            out = fn(*args, **kwargs)
            for _ in range(times - 1):
                out = fn(*args, **kwargs)
            return out
        return inner
    return wrap


def bind[T, **P, R](tag: T) -> Callable[[Callable[Concatenate[T, P], R]], Callable[P, R]]:
    def deco(fn: Callable[Concatenate[T, P], R]) -> Callable[P, R]:
        def inner(*args: P.args, **kwargs: P.kwargs) -> R:
            return fn(tag, *args, **kwargs)
        return inner
    return deco


@retry(2)
@bind(3.5)
def scale(factor: float, name: str, *, times: int = 1) -> str:
    return name.upper() * times


reveal_type(scale)
print(scale('ab', times=2))
try:
    scale(1, times=2)  # expect-error: int is not assignable to str
except AttributeError as exc:
    print('runtime:', type(exc).__name__)
try:
    scale('ab', count=2)  # expect-error: no keyword argument named count
except TypeError as exc:
    print('runtime:', type(exc).__name__)
